# Sole-trader ownership is a documented legal identity, not mere correlation.
if(!exists('build_retail_sme_features'))library(creditratingsystem)
rj_owner_helper<-'creditratingsystem-r/examples/retail_application_journey.R';if(!file.exists(rj_owner_helper))rj_owner_helper<-system.file('examples','retail_application_journey.R',package='creditratingsystem');source(rj_owner_helper)
run_retail_owner_journey<-function(data=NULL,verify_reference=TRUE,return_artifacts=FALSE,applications_path=NULL,releases_path=NULL,include_lifecycle=TRUE){
 if(is.null(data))data<-jsonlite::read_json(rj_resource('retail_owner_journey.json'),simplifyVector=FALSE);product<-'RETAIL_SMALL_BUSINESS_FINANCE';case<-data$products[[product]];business<-list()
 for(i in seq_along(case$owner_business_inputs)){row<-case$owner_business_inputs[[i]];h<-case$households[[i]];graph<-do.call(build_customer_household_graph,row$household_graph);obligations<-do.call(aggregate_household_obligations,c(row$household_obligations,list(household_graph=graph)));features<-do.call(build_retail_sme_features,c(row$features,list(household_obligations=obligations)))$value;groups<-assign_default_groups(do.call(build_entity_graph,row$legal_graph),row$default_policy,row$facility_mappings)$value
 if(features$owner_draw_business_outflows+row$other_household_income!=h$monthly_income)stop('Owner transfers and household income do not reconcile')
 if(verify_reference)stopifnot(features$owner_draw_business_outflows==features$matched_owner_draw_household_inflows,features$owner_draw_business_outflows==row$expected_owner_draw,features$cash_after_business_debt==row$expected_after_business_debt,features$cash_after_business_and_household_debt==row$expected_after_business_debt,length(groups$groups)==1)
 business[[i]]<-list(application_id=row$application_id,features=features,household=obligations$value,default_groups=groups)
 }
 chain<-run_retail_application_journey(data,verify_reference=verify_reference,applications_path=if(is.null(applications_path))rj_resource('owner_applications.json')else applications_path,releases_path=if(is.null(releases_path))rj_resource('owner_releases.json')else releases_path,return_artifacts=TRUE);presentation<-rj_presentation(chain)
 presentation$business_cash_conservation<-lapply(business,function(r)list(application_id=r$application_id,business_after_current_debt=r$features$cash_after_business_debt,owner_transfer_out=r$features$owner_draw_business_outflows,owner_transfer_in=r$features$matched_owner_draw_household_inflows,household_debt_service=r$household$households[[1]]$total_budget_debt_service,legal_default_groups=length(r$default_groups$groups)))
 lifecycle<-NULL
 if(include_lifecycle){p<-'creditratingsystem-r/examples/retail_owner_lifecycle.R';if(!file.exists(p))p<-system.file('examples','retail_owner_lifecycle.R',package='creditratingsystem');source(p);lifecycle<-run_retail_owner_lifecycle(case,chain$products[[product]],data$evaluation_cutoff,verify_reference);presentation$lifecycle<-list(account_id=lifecycle$account_id,application_id=lifecycle$application_id,proposal_status=case$lifecycle$proposal_status,proposal_remaining_claim=lifecycle$proposal$candidate$remaining_claim,actual_default_ead=lifecycle$ead$conditional_ead[[1]],realized_principal_loss=lifecycle$workout$economic_loss,predicted_lgd=round(lifecycle$predicted_lgd,8),portfolio_expected_loss=round(lifecycle$portfolio$distribution$expected_loss,2),paired_brier_difference=round(lifecycle$benchmark$result$metrics$paired_differences$candidate$brier$difference,8),override_rate=lifecycle$benchmark$overrides$metrics$override_rate,terminal_state=lifecycle$terminal_state,replay_status=lifecycle$replay$decision$status,first30day_expected_loss=round(lifecycle$forecast_horizon_loss$lifetime_expected_loss,2),prior_event_survival=lifecycle$prior_event_curve$curves[[1]]$survival,phase_status=list(ORIGINATION='ACTUAL_APPLICATION_AND_FUNDING',PERFORMING='DATED_ACCOUNT_PREDICTIONS',REVIEW_EARLY_WARNING='OBSERVED_ARREARS_AND_PAIRED_REVIEW',DELINQUENCY='UNPAID100_DPD5',RESTRUCTURING='OFFERED_NOT_ACCEPTED',DEFAULT_WORKOUT='ACTUAL600_PRINCIPAL_RECOVERY',EXIT='DOCUMENTED_FULL_AND_FINAL_SETTLEMENT',PORTFOLIO_MONITORING='ORIGINAL_TWO_LOAN_BOOK_AND_HELDOUT_VALIDATORS'))}
 if(return_artifacts)list(presentation=presentation,application_chain=chain,business=business,lifecycle=lifecycle,source_case=case,evaluation_cutoff=data$evaluation_cutoff)else presentation
}
